<template>
  <section class="mx-auto max-w-7xl px-3 py-10 sm:px-6"><div class="flex flex-wrap items-end justify-between gap-5"><div><p class="text-xs uppercase tracking-[.3em] text-cyan-200">Recognition</p><h1 class="mt-3 text-3xl font-black">Certificates</h1><p class="mt-3 text-slate-400">Issue and maintain participant certificates.</p></div><button class="primary" @click="openCreate">+ Issue certificate</button></div>
    <label class="field mt-8 block max-w-md"><span>Event</span><select v-model="eventId"><option v-for="event in events" :key="event.id" :value="event.id">{{event.name}}</option></select></label><p v-if="feedback" class="mt-5 rounded-2xl border border-cyan-300/20 bg-cyan-300/10 p-4">{{feedback}}</p>
    <div class="mt-6 overflow-x-auto rounded-[2rem] border border-white/10 bg-slate-950/45 data-table-shell"><table class="w-full min-w-full text-left md:min-w-[900px]"><thead><tr><th>Certificate</th><th>User</th><th>Issued</th><th>Download</th><th class="text-right">Actions</th></tr></thead><tbody><tr v-if="loading"><td colspan="5" class="py-12 text-center">Loading...</td></tr><tr v-else-if="!items.length"><td colspan="5" class="py-12 text-center">No certificates issued.</td></tr><tr v-for="item in items" v-else :key="item.id"><td data-label="Certificate"><strong class="break-words">{{item.title}}</strong><small class="break-words">{{item.certificate_number}}</small></td><td data-label="User" class="break-words">{{userLabel(item.user_id)}}</td><td data-label="Issued">{{formatDate(item.issued_at)}}</td><td data-label="Download"><a v-if="item.download_url" :href="item.download_url" target="_blank" rel="noopener" class="break-all text-cyan-200">Open file</a><span v-else>—</span></td><td data-label="Actions" class="cell-actions"><div class="flex flex-wrap justify-end gap-2"><NuxtLink class="table-button text-cyan-200" :to="{ path: '/admin/translations', query: { entity_type: 'certificate', entity_id: item.id } }">Chinese translation</NuxtLink><button class="table-button" @click="openEdit(item)">Edit</button><button class="table-button text-red-200" @click="remove(item)">Delete</button></div></td></tr></tbody></table></div>
    <Teleport to="body"><div v-if="modalOpen" class="backdrop" @click.self="close"><form class="modal" @submit.prevent="save"><header><div><p class="text-xs uppercase tracking-[.25em] text-cyan-200">Certificate editor</p><h2>{{editingId?'Update':'Issue'}} certificate</h2></div><button type="button" @click="close">×</button></header><main><label class="field"><span>Recipient</span><select v-model="form.user_id" required><option value="" disabled>Select user</option><option v-for="user in users" :key="user.id" :value="user.id">{{user.full_name||user.email}} — {{user.email}}</option></select></label><div class="grid gap-4 sm:grid-cols-2"><label class="field"><span>Certificate number</span><input v-model.trim="form.certificate_number" required /></label><label class="field"><span>Issued at</span><input v-model="form.issued_at" type="datetime-local" /></label></div><label class="field"><span>Title</span><input v-model.trim="form.title" required /></label><label class="field"><span>Download URL</span><input v-model.trim="form.download_url" type="url" /></label></main><footer><button type="button" class="secondary" @click="close">Cancel</button><button class="primary" :disabled="saving">{{saving?'Saving...':'Save'}}</button></footer></form></div></Teleport>
  </section>
</template>
<script setup lang="ts">
import{useAdminOperations,type AdminUserItem,type CertificatePayload}from'~/composables/useAdminOperations';import{useEvent,type EventItem}from'~/composables/useEvent';import type{CertificateItem}from'~/composables/useEventUpdates';
definePageMeta({middleware:['auth','admin']});useSeoMeta({title:'Manage Certificates | IWBIF 2026'});const api=useAdminOperations(),{getEvents}=useEvent();const{data:eventResponse}=await useAsyncData('certificate-events',()=>getEvents(1,100));const events=computed<EventItem[]>(()=>eventResponse.value?.data||[]),eventId=ref(events.value[0]?.id||''),users=ref<AdminUserItem[]>([]),items=ref<CertificateItem[]>([]),loading=ref(false),saving=ref(false),modalOpen=ref(false),editingId=ref(''),feedback=ref('');type Form={user_id:string;certificate_number:string;title:string;download_url:string;issued_at:string};const empty=():Form=>({user_id:'',certificate_number:'',title:'Certificate of Attendance',download_url:'',issued_at:''}),form=reactive(empty());const errorText=(e:unknown)=>(e as {data?:{message?:string}}).data?.message||(e instanceof Error?e.message:'Operation failed.');const local=(v?:string|null)=>v?new Date(new Date(v).getTime()-new Date(v).getTimezoneOffset()*60000).toISOString().slice(0,16):'';
const load=async()=>{if(!eventId.value)return;loading.value=true;try{const[result,userResult]=await Promise.all([api.getAdminCertificates(eventId.value),api.getUsers(1,100)]);items.value=result.data||[];users.value=userResult.data||[];}catch(e){feedback.value=errorText(e);}finally{loading.value=false;}};const openCreate=()=>{editingId.value='';Object.assign(form,empty());modalOpen.value=true;};const openEdit=(item:CertificateItem)=>{editingId.value=item.id;Object.assign(form,{user_id:item.user_id||'',certificate_number:item.certificate_number,title:item.title,download_url:item.download_url||'',issued_at:local(item.issued_at)});modalOpen.value=true;};const close=()=>modalOpen.value=false;const save=async()=>{saving.value=true;const payload:CertificatePayload={event_id:eventId.value,user_id:form.user_id,certificate_number:form.certificate_number,title:form.title,download_url:form.download_url||null,issued_at:form.issued_at?new Date(form.issued_at).toISOString():null};try{if(editingId.value)await api.updateCertificate(editingId.value,payload);else await api.createCertificate(payload);feedback.value='Certificate saved.';close();await load();}catch(e){feedback.value=errorText(e);}finally{saving.value=false;}};const remove=async(item:CertificateItem)=>{if(!confirm(`Delete certificate "${item.certificate_number}"?`))return;try{await api.deleteCertificate(item.id);await load();}catch(e){feedback.value=errorText(e);}};watch(eventId,load);if(eventId.value)await load();const userLabel=(id?:string)=>{const user=users.value.find(item=>item.id===id);return user?.full_name||user?.email||id||'—';};const formatDate=(v?:string|null)=>v?new Intl.DateTimeFormat('en-GB',{dateStyle:'medium'}).format(new Date(v)):'—';
</script>
<style scoped>
